import{_ as e,a as o,b as a,c as n}from"./chunks/state_monitoring4.4vb6Ou65.js";import{c as i,Q as r,j as s,m as c}from"./chunks/framework.DjobWxAB.js";const b=JSON.parse('{"title":"State Monitoring","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/GUI/state-monitoring.md","filePath":"manual/GUI/state-monitoring.md","lastUpdated":1779182288000}'),l={name:"manual/GUI/state-monitoring.md"};function g(p,t,m,d,u,h){return r(),s("div",null,[...t[0]||(t[0]=[c('<h1 id="state-monitoring" tabindex="-1">State Monitoring <a class="header-anchor" href="#state-monitoring" aria-label="Permalink to &quot;State Monitoring&quot;">​</a></h1><p>In RBQGUI, you can check the robot’s current status (emergency/power/sensors/perception modules) in real time.</p><h2 id="_1-top-status-area" tabindex="-1">1) Top Status Area <a class="header-anchor" href="#_1-top-status-area" aria-label="Permalink to &quot;1) Top Status Area&quot;">​</a></h2><p>As shown in <code>state_monitoring1.png</code>, the top area displays <code>EMERGENCY</code> status and various system status icons (battery/connection/power, etc.).</p><figure style="margin-top:1rem;text-align:center;"><img src="'+e+'" alt="Top status area" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Top status area</figcaption></figure><h2 id="_2-diagnostic-table-motors-imu-etc" tabindex="-1">2) Diagnostic Table (Motors/IMU, etc.) <a class="header-anchor" href="#_2-diagnostic-table-motors-imu-etc" aria-label="Permalink to &quot;2) Diagnostic Table (Motors/IMU, etc.)&quot;">​</a></h2><p>In <code>state_monitoring2.png</code>, you can review diagnostic values per leg/joint (e.g., HRR/HRP/...) along with readings such as temperature, gyro, and acceleration (ACC) in a table.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+o+'" alt="Diagnostic table" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Joint/Sensor diagnostic table</figcaption></figure><h3 id="joint-naming" tabindex="-1">Joint Naming <a class="header-anchor" href="#joint-naming" aria-label="Permalink to &quot;Joint Naming&quot;">​</a></h3><p>Joint IDs in the diagnostic table use the following abbreviations:</p><ul><li><strong>HRR</strong> : Hind Right Roll, <strong>HRP</strong> : Hind Right Pitch, <strong>HRK</strong> : Hind Right Knee</li><li><strong>HLR</strong> : Hind Left Roll, <strong>HLP</strong> : Hind Left Pitch, <strong>HLK</strong> : Hind Left Knee</li><li><strong>FRR</strong> : Front Right Roll, <strong>FRP</strong> : Front Right Pitch, <strong>FRK</strong> : Front Right Knee</li><li><strong>FLR</strong> : Front Left Roll, <strong>FLP</strong> : Front Left Pitch, <strong>FLK</strong> : Front Left Knee</li></ul><h2 id="_3-perception-status" tabindex="-1">3) Perception Status <a class="header-anchor" href="#_3-perception-status" aria-label="Permalink to &quot;3) Perception Status&quot;">​</a></h2><p>As shown in <code>state_monitoring3.png</code>, you can toggle perception-related modules (e.g., IR projector, night vision, LED buzzer, etc.), and check module operation/error/count values (Fail/Count).</p><figure style="margin-top:1rem;text-align:center;"><img src="'+a+'" alt="Perception status" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Perception module status</figcaption></figure><h2 id="_4-power-switch-module-check" tabindex="-1">4) Power Switch &amp; Module Check <a class="header-anchor" href="#_4-power-switch-module-check" aria-label="Permalink to &quot;4) Power Switch &amp; Module Check&quot;">​</a></h2><p>In <code>state_monitoring4.png</code>, you can check power switch states (Vision Computer/Cameras/sensors such as LiDAR) and also review major power/load status like BAT/LEGS/ADDON/EXTERN/CHARGE. Use <code>Reset</code> and <code>Check</code> to refresh the status.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+n+'" alt="Power switch and module check" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Power switch &amp; module check</figcaption></figure><h2 id="notes-warnings" tabindex="-1">Notes / Warnings <a class="header-anchor" href="#notes-warnings" aria-label="Permalink to &quot;Notes / Warnings&quot;">​</a></h2><ul><li>If <code>EMERGENCY</code> or an abnormal state is shown, secure safety first and then check the cause (sensor/power/perception module operation, etc.).</li><li>If perception/sensor modules are OFF, the corresponding features (e.g., vision-based walking) may be limited.</li></ul>',19)])])}const R=i(l,[["render",g]]);export{b as __pageData,R as default};
